import Link from 'next/link';
import { getCloudflareContext } from "@opennextjs/cloudflare";

export const dynamic = 'force-dynamic';

export default async function RootLayout({ children }) {
  let pages = [];

  try {
    const { env } = await getCloudflareContext();
    if (env && env.palimian) {
      const { results } = await env.palimian.prepare('SELECT * FROM pages').all();
      pages = results || [];
    }
  } catch (error) {
    console.error("Database Error:", error);
  }

  return (
    <html lang="th">
      <body style={{ margin: 0, display: 'flex', flexDirection: 'column', minHeight: '100vh', position: 'relative' }}>
        
        {/* แถบด้านบนสุด (Navbar) */}
        <header style={{ 
          position: 'absolute', 
          top: 0, 
          left: 0, 
          width: '100%', 
          padding: '1.2rem 2rem', 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center', 
          boxSizing: 'border-box', 
          zIndex: 1000, 
          fontFamily: 'serif' 
        }}>
          {/* ชื่อเว็บทางซ้ายสุด */}
          <Link href="/" style={{ fontSize: '1.2rem', fontWeight: 'bold', color: '#1A1A1A', textDecoration: 'none', letterSpacing: '1px' }}>
            PALIMIAN
          </Link>

          {/* รายการเมนูลิงก์ด้านขวา (ดึงจาก D1 Database โดยตรง) */}
          <div style={{ display: 'flex', gap: '1.5rem', alignItems: 'center', fontFamily: 'sans-serif' }}>
            <Link href="/" style={{ color: '#1A1A1A', textDecoration: 'none', fontSize: '0.95rem' }}>
              หน้าแรก
            </Link>

            {pages.length > 0 ? (
              pages.map((page) => (
                <Link 
                  key={page.id || page.slug_path} 
                  href={`/${page.slug_path}`} 
                  style={{ color: '#1A1A1A', textDecoration: 'none', fontSize: '0.95rem' }}
                >
                  {page.title}
                </Link>
              ))
            ) : (
              // เมนูสำรองกรณีดึงข้อมูลไม่ทัน เพื่อไม่ให้เมนูหายไป
              <>
                <Link href="/Jewelry" style={{ color: '#1A1A1A', textDecoration: 'none', fontSize: '0.95rem' }}>
                  Support My Jewelry
                </Link>
                <Link href="/Signs" style={{ color: '#1A1A1A', textDecoration: 'none', fontSize: '0.95rem' }}>
                  Graphics for Signs
                </Link>
              </>
            )}
          </div>
        </header>

        {/* เนื้อหาหลัก */}
        <div style={{ flex: 1, paddingTop: '4rem' }}>
          {children}
        </div>
        
        {/* แถบช่องทางติดต่อด้านล่างทุกหน้า */}
        <footer style={{ backgroundColor: '#1A1A1A', color: '#FFF', padding: '1.5rem 2rem', fontFamily: 'sans-serif', marginTop: 'auto' }}>
          <div style={{ maxWidth: '1100px', margin: '0 auto', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem' }}>
            <div>
              <p style={{ margin: 0, fontWeight: 'bold', fontSize: '1.1rem' }}>ช่องทางติดต่อเรา</p>
              <p style={{ margin: '0.25rem 0 0 0', fontSize: '0.9rem', color: '#ccc' }}>โทร: 02-XXX-XXXX | อีเมล: palimian.varee@gmail.com</p>
            </div>
            <div style={{ display: 'flex', gap: '1rem', fontSize: '0.9rem' }}>
              <span style={{ color: '#ccc' }}>Line: @978wnmxg</span>
              <span style={{ color: '#ccc' }}>Facebook: MyWebsite</span>
            </div>
          </div>
        </footer>
      </body>
    </html>
  );
}